  // 2. Delegated Event Listeners (For elements inside dynamic details panels)
  document.addEventListener('click', (event) => {
    const target = event.target;
    if (!target) return;

    if (target.id === 'right-panel-close-btn') {
      toggleRightPanel(false);
    }
    else if (target.id === 'button-view-full-data-table-zone-details') {
      openFullDataView();
    }
    else if (target.id === 'button-close-zone-details') {
      clearZoneSelection();
    }
    else if (target.id === 'button-copy-top-25-zone-details') {
      copyZoneSocieties(event);
    }
    else if (target.id === 'button-copy-top-25-zone-details-2') {
      copyZoneHospitalsMarkets(event);
    }

    else if (target.id === 'button-clear-catchment-results') {
      clearCatchmentSelection();
    }
    else if (target.id === 'button-copy-top-25-catchment-results') {
      copyCatchmentSocieties(event);
    }

    else if (target.id === 'button-close-commercial-details') {
      clearCommercialSelection();
    }
    else if (target.id === 'button-clear-commercial-comparison') {
      clearCommercialComparison();
    }
    else if (target.id === 'button-close-market-details') {
      clearMarketSelection();
    }
    else if (target.id === 'toggle-market-all' || target.id === 'toggle-market-societies' || target.id === 'toggle-market-offices' || target.id === 'toggle-market-hospitals') {
      updateMarketMapLayers();
    }
    else if (target.id === 'button-close-hex-details') {
      clearHexSelection();
    }
  });

